// smoke.spec.js — Audio Waveform Image Maker: the core action on the bundled fictional fixture
// tests/fixtures/sample-song.mp3 (generated by tests/tools/make-sample-song.js).
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);

function pngInfo(bytes) {
  expect(bytes.subarray(1, 4).toString('latin1')).toBe('PNG');
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20), colorType: bytes[25] };
}

function silentWav(seconds = 2, rate = 8000) {
  const n = seconds * rate;
  const b = Buffer.alloc(44 + n * 2);
  b.write('RIFF', 0); b.writeUInt32LE(36 + n * 2, 4); b.write('WAVE', 8);
  b.write('fmt ', 12); b.writeUInt32LE(16, 16); b.writeUInt16LE(1, 20); b.writeUInt16LE(1, 22);
  b.writeUInt32LE(rate, 24); b.writeUInt32LE(rate * 2, 28); b.writeUInt16LE(2, 32); b.writeUInt16LE(16, 34);
  b.write('data', 36); b.writeUInt32LE(n * 2, 40);
  return b;
}

async function loadSong(page, name = 'sample-song.mp3') {
  await page.setInputFiles('#file-input', { name, mimeType: 'audio/mpeg', buffer: fs.readFileSync(fixture('sample-song.mp3')) });
  await expect(page.locator('#info-line')).toContainText('Duration 0:12', { timeout: 15_000 });
  await expect(page.locator('#download-png')).toBeEnabled();
  await page.waitForTimeout(150); // let the requestAnimationFrame redraw land
}

/** Samples the preview canvas: background corner, how many pixels match a color, and column heights. */
async function canvasStats(page, rgb) {
  return page.evaluate((target) => {
    const c = document.getElementById('preview');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    const px = (x, y) => { const i = (y * c.width + x) * 4; return [d[i], d[i + 1], d[i + 2], d[i + 3]]; };
    const bg = px(1, 1);
    let match = 0, painted = 0;
    const heights = [];
    for (let x = 0; x < c.width; x += 2) {
      let h = 0;
      for (let y = 0; y < c.height; y++) {
        const p = px(x, y);
        const differs = Math.abs(p[0] - bg[0]) + Math.abs(p[1] - bg[1]) + Math.abs(p[2] - bg[2]) + Math.abs(p[3] - bg[3]) > 40;
        if (differs) { h++; painted++; }
        if (target && Math.abs(p[0] - target[0]) < 30 && Math.abs(p[1] - target[1]) < 30 && Math.abs(p[2] - target[2]) < 30 && p[3] > 200) match++;
      }
      heights.push(h);
    }
    return { bg, match, painted, heights, url: c.toDataURL() };
  }, rgb || null);
}

test.describe('Audio Waveform Image Maker', () => {
  test('empty state shows a sample preview and disabled downloads', async ({ page }) => {
    await page.goto('./');
    await expect(page.locator('#preview')).toBeVisible();
    await expect(page.locator('#download-png')).toBeDisabled();
    const s = await canvasStats(page);
    expect(s.painted).toBeGreaterThan(500);
  });

  test('loading sample-song.mp3 draws a waveform preview in the default colors', async ({ page }) => {
    await page.goto('./');
    await loadSong(page);
    await expect(page.locator('#info-line')).toContainText('48 kHz');
    await expect(page.locator('#info-line')).toContainText('Mono');
    await expect(page.locator('#info-line')).toContainText('Peak');
    await expect(page.locator('#results .result')).toContainText('sample-song.mp3');
    const s = await canvasStats(page);
    // default background #11131c
    expect(s.bg.slice(0, 3)).toEqual([17, 19, 28]);
    expect(s.bg[3]).toBe(255);
    // default gradient #7c6cf2 → #22d3ee: purple on the left, cyan on the right
    const ends = await page.evaluate(() => {
      const c = document.getElementById('preview');
      const ctx = c.getContext('2d');
      const y = Math.floor(c.height / 2);
      const find = (from, dir) => { for (let x = from; x >= 0 && x < c.width; x += dir) { const p = ctx.getImageData(x, y, 1, 1).data; if (p[0] + p[1] + p[2] > 200) return [...p]; } return null; };
      return { left: find(0, 1), right: find(c.width - 1, -1) };
    });
    expect(ends.left[2]).toBeGreaterThan(200); // blue-ish purple
    expect(ends.left[0]).toBeGreaterThan(ends.left[1]); // more red than green: purple
    expect(ends.right[1]).toBeGreaterThan(ends.right[0]); // more green than red: cyan
    // three loud sections and quiet gaps: bar heights vary a lot
    const tall = Math.max(...s.heights);
    const short = Math.min(...s.heights.filter((h) => h > 0));
    expect(tall).toBeGreaterThan(short * 5);
  });

  test('changing bar style to Bars and color to a new value updates the preview', async ({ page }) => {
    await page.goto('./');
    await loadSong(page);
    await page.selectOption('#style', 'lines');
    await page.waitForTimeout(150);
    await expect(page.locator('#preview')).toHaveAttribute('data-style', 'lines');
    const before = await canvasStats(page);
    await page.selectOption('#style', 'bars');
    await page.uncheck('#gradient');
    await page.locator('#color').fill('#ff3300');
    await page.waitForTimeout(150);
    await expect(page.locator('#preview')).toHaveAttribute('data-style', 'bars');
    const after = await canvasStats(page, [255, 51, 0]);
    expect(after.url).not.toBe(before.url);
    expect(after.match).toBeGreaterThan(1000);
  });

  test('Download PNG yields an image of the chosen width and height', async ({ page }) => {
    await page.goto('./');
    await loadSong(page);
    await page.selectOption('#size', 'custom');
    await page.fill('#width', '800');
    await page.fill('#height', '300');
    await page.locator('#height').dispatchEvent('change');
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download-png')]);
    expect(download.suggestedFilename()).toBe('sample-song-waveform.png');
    const bytes = fs.readFileSync(await download.path());
    const info = pngInfo(bytes);
    expect(info).toMatchObject({ width: 800, height: 300 });

    const [d2] = await Promise.all([page.waitForEvent('download'), page.selectOption('#size', '1500x500').then(() => page.click('#download-png'))]);
    expect(pngInfo(fs.readFileSync(await d2.path()))).toMatchObject({ width: 1500, height: 500 });
  });

  test('Download SVG yields a file that contains path or rect elements', async ({ page }) => {
    await page.goto('./');
    await loadSong(page);
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download-svg')]);
    expect(download.suggestedFilename()).toBe('sample-song-waveform.svg');
    const svg = fs.readFileSync(await download.path(), 'utf8');
    expect(svg).toMatch(/^<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="1920" height="1080"/);
    expect((svg.match(/<rect /g) || []).length).toBeGreaterThan(50);
    expect(svg).toContain('linearGradient');

    await page.selectOption('#style', 'outline');
    const [d2] = await Promise.all([page.waitForEvent('download'), page.click('#download-svg')]);
    const svg2 = fs.readFileSync(await d2.path(), 'utf8');
    expect(svg2).toMatch(/<path d="M[\d.]+ [\d.]+L/);
    // the SVG renders in the browser
    const ok = await page.evaluate(async (text) => {
      const img = new Image();
      img.src = URL.createObjectURL(new Blob([text], { type: 'image/svg+xml' }));
      await img.decode();
      return img.naturalWidth;
    }, svg2);
    expect(ok).toBe(1920);
  });

  test('a transparent background option produces a PNG with alpha', async ({ page }) => {
    await page.goto('./');
    await loadSong(page);
    await page.check('#transparent');
    await expect(page.locator('#preview-wrap')).toHaveClass(/is-transparent/);
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download-png')]);
    const bytes = fs.readFileSync(await download.path());
    expect(pngInfo(bytes).colorType).toBe(6); // RGBA
    const alpha = await page.evaluate(async (b64) => {
      const blob = await (await fetch(`data:image/png;base64,${b64}`)).blob();
      const bmp = await createImageBitmap(blob);
      const c = new OffscreenCanvas(bmp.width, bmp.height);
      const ctx = c.getContext('2d');
      ctx.drawImage(bmp, 0, 0);
      const row = ctx.getImageData(0, Math.floor(bmp.height / 2), bmp.width, 1).data;
      let opaque = 0;
      for (let i = 3; i < row.length; i += 4) if (row[i] === 255) opaque++;
      return { corner: ctx.getImageData(2, 2, 1, 1).data[3], middle: opaque };
    }, bytes.toString('base64'));
    expect(alpha.corner).toBe(0);
    expect(alpha.middle).toBeGreaterThan(100); // the bars themselves are opaque
  });

  test('works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await loadSong(page);
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    const canvasBox = await page.locator('#preview').boundingBox();
    const optionsBox = await page.locator('#options').boundingBox();
    expect(canvasBox.width).toBeGreaterThan(250);
    expect(optionsBox.y).toBeGreaterThan(canvasBox.y + canvasBox.height); // options collapse under the preview
    await page.selectOption('#size', 'custom');
    const after = await page.evaluate(() => document.documentElement.scrollWidth);
    expect(after).toBeLessThanOrEqual(391);
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download-png')]);
    expect(pngInfo(fs.readFileSync(await download.path())).width).toBe(1920);
  });

  test('rejects non-audio files, also when mixed with a valid one', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', [fixture('sample.png'), fixture('sample-song.mp3')]);
    await expect(page.locator('#results .alert--error')).toContainText('sample.png is not an audio file');
    await expect(page.locator('#info-line')).toContainText('Duration 0:12');
    await page.setInputFiles('#file-input', fixture('sample.pdf'));
    await expect(page.locator('#results .alert--error')).toContainText('sample.pdf');
  });

  test('undecodable audio shows an inline error', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', { name: 'broken.mp3', mimeType: 'audio/mpeg', buffer: Buffer.from('this is not really audio '.repeat(40)) });
    await expect(page.locator('#results .alert--error')).toContainText('Could not decode broken.mp3', { timeout: 15_000 });
    await expect(page.locator('#download-png')).toBeDisabled();
  });

  test('silence draws a flat line and says so; the WAV sample rate is reported', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', { name: 'quiet-room.wav', mimeType: 'audio/wav', buffer: silentWav() });
    await expect(page.locator('#info-line')).toContainText('8 kHz');
    await expect(page.locator('#results')).toContainText('silent');
    await expect(page.locator('#preview')).toHaveAttribute('data-silent', 'true');
    const s = await canvasStats(page);
    const heights = s.heights.filter((h) => h > 0);
    expect(Math.max(...heights)).toBeLessThanOrEqual(4);
  });

  test('Enter downloads PNG, unicode file names are kept, range is applied', async ({ page }) => {
    await page.goto('./');
    await loadSong(page, 'Café Ñandú 夜.mp3');
    await page.fill('#start', '4');
    await page.fill('#end', '0:07');
    await expect(page.locator('#range-hint')).toContainText('Drawing 0:04.0 to 0:07.0');
    await page.focus('#style');
    const [download] = await Promise.all([page.waitForEvent('download'), page.keyboard.press('Enter')]);
    expect(download.suggestedFilename()).toBe('Café Ñandú 夜-waveform.png');
    await page.fill('#end', '2');
    await expect(page.locator('#range-hint')).toContainText('End must be after start');
  });

  test('files longer than ten minutes are analysed in a Web Worker', async ({ page }) => {
    await page.goto('./');
    const workerRequest = page.waitForRequest(/worker\.js$/);
    const wav = silentWav(11 * 60, 4000);
    for (let i = 44 + 2 * 4000 * 60; i < 44 + 2 * 4000 * 120; i += 2) wav.writeInt16LE((i / 2) % 40 < 20 ? 12000 : -12000, i); // one loud minute
    await page.setInputFiles('#file-input', { name: 'long-talk.wav', mimeType: 'audio/wav', buffer: wav });
    await workerRequest;
    await expect(page.locator('#info-line')).toContainText('Duration 11:00', { timeout: 30_000 });
    await expect(page.locator('#preview')).toHaveAttribute('data-silent', 'false');
    await expect(page.locator('#progress')).toBeHidden();
  });

});
